INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1xptg6leuu', 'course-bili-bv1xptg6leuu', '100001', '0', 'BILI-OPS-4U7S9A', 'course-category-operations', 'instructor-bili-3546722766686941', 'AI 怎么写 SEO 文章？我用 Claude 半年做到 2 万点击的完整教程', '1 讲完整课程 · 32 分钟', '用 AI 写 SEO 文章，最常见的问题不是写不出来，是写出来没排名。这支影片把我半年来的完整流程从头做一次给你看： 关键词怎么查、项目怎么设置、指令和参考文件各放什么、 第一版产出之后要改什么、哪些地方一定要人工介入', '课程简介：用 AI 写 SEO 文章，最常见的问题不是写不出来，是写出来没排名。这支影片把我半年来的完整流程从头做一次给你看： 关键词怎么查、项目怎么设置、指令和参考文件各放什么、 第一版产出之后要改什么、哪些地方一定要人工介入。实际成绩：Google Search Console 上半年从 0 做到 2.15 万点击、52.5 万曝光、平均排名 7.1，累积 100 多篇文章。全部用 Claude 产出，人工审阅后上线。不是「把标题丢给 AI 就有文章」那种教程。中间每一个判断点我都会说明为什么。▬▬▬▬▬ 章节 ▬▬▬▬▬ 0:00 开场：六个月的实际数据 2:27 SEO 的两个面向 3:12 Claude 的三种用法 4:06 建立项目 5:43 先知道你在写给谁 7:49 查真实搜索量 12:32 让它写指令和参考文件 14:50 主题集群 Topic Cluster 17:41 将指令上传 20:31 集群文件上传到参考文件 21:04 实际产出第一篇 22:39 第一版之后还会再改 24:25 一定要人工看过 29:15 指令不能无限长 30:50 数字一定要人工查证 31:39 收尾 ▬▬▬▬▬ 一则更正 ▬▬▬▬▬ 影片中提到「用 App 的话一次只能在一个聊天室进行」，现在 App 也可以同时开多个聊天室了，在界面的左侧就能切换。▬▬▬▬▬ 关于我 ▬▬▬ 课程结构：共 1 章 1 讲，累计时长 32 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握内容选题、脚本、拍摄与剪辑的完整生产链路","理解平台推荐机制与账号冷启动方法","搭建可复用的内容日历、数据复盘与投放模型","具备从零起号到商业变现的实战能力"]', '["零基础想做新媒体运营的职场人","需要提升账号数据的自媒体创作者","实体商家与品牌市场人员"]', '["有常用社交平台的真实使用经验","无需拍摄设备，手机即可完成练习"]', 'intermediate', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/c1b827bd7650a151d96d8744b06fd2b353d0a345.jpg', '["运营营销","新媒体","增长实战","AI","怎么写","SEO"]', 1939, 1, 107, '4.7', 51, 'BV1xptg6LEUU', NULL, NULL, NULL, 1, 0, 'standard', NULL, 'Roy的独立站笔记', 0, 'tenant', 'published', '2026-09-01T03:32:51.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
